{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "Before taking any actions that update the booking database (booking, modifying flights, editing baggage, changing cabin class, or updating passenger information), you must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "requirement": "The assistant must obtain explicit user confirmation (e.g., 'yes') before proceeding with any action that updates the booking database, including cancellations."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "The agent must also obtain the reason for cancellation (change of plan, airline cancelled flight, or other reasons).",
      "requirement": "The assistant must confirm the reason for cancellation (e.g., 'change of plan') before proceeding with the cancellation."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "If any portion of the flight has already been flown, the agent cannot help and transfer is needed.",
      "requirement": "The assistant must ensure that no portion of the flight has already been flown before proceeding with cancellation. **Exception:** If the flight has already departed, the assistant must transfer the user to a human agent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "Otherwise, flight can be cancelled if any of the following is true:\n- The booking was made within the last 24 hrs\n- The flight is cancelled by airline\n- It is a business flight\n- The user has travel insurance and the reason for cancellation is covered by insurance.",
      "requirement": "The assistant must verify that the cancellation complies with at least one of the following conditions: booking within the last 24 hours, flight cancellation by the airline, business cabin class, or travel insurance covering the cancellation reason."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "The API does not check that cancellation rules are met, so the agent must make sure the rules apply before calling the API!",
      "requirement": "The assistant must ensure all cancellation rules are met before making the `cancel_reservation` tool call."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "The agent must obtain the user id and reservation id.",
      "requirement": "The assistant must ensure the `cancel_reservation` tool call includes a valid `reservation_id` and that the user ID matches the reservation owner."
    }
  ]
}
